import{_ as t,c as p,a2 as e,o as s}from"./chunks/framework.CqbvlPrP.js";const r="/assets/1.BXf04gBy.jpg",o="/assets/2.GphaluEK.jpg",i="/assets/3.BhldjjJv.jpg",l="/assets/4.DRXYwNU9.jpg",c="/assets/5.l1Fp4wyt.jpg",g=JSON.parse('{"title":"先说答案，二者完全可以兼顾，具体用法如下","description":"","frontmatter":{},"headers":[],"relativePath":"stock/建仓/突破建仓与回调建仓/突破回调兼顾.md","filePath":"stock/建仓/突破建仓与回调建仓/突破回调兼顾.md"}'),n={name:"stock/建仓/突破建仓与回调建仓/突破回调兼顾.md"};function h(_,a,d,m,u,f){return s(),p("div",null,a[0]||(a[0]=[e('<h1 id="先说答案-二者完全可以兼顾-具体用法如下" tabindex="-1">先说答案，二者完全可以兼顾，具体用法如下 <a class="header-anchor" href="#先说答案-二者完全可以兼顾-具体用法如下" aria-label="Permalink to &quot;先说答案，二者完全可以兼顾，具体用法如下&quot;">​</a></h1><p>a、窄幅震荡时突破介入，非窄幅震荡时回调介入。</p><p>b、强趋势时突破介入，弱趋势时回调介入。</p><p>c、趋势起步期和末期回调介入，中期突破介入。</p><p>下面详细说说</p><p>只要去复盘，你会发现，突破和回调介入都对，都有成功的经典案例，那到底怎么进场呢？</p><h2 id="其实这要分析3个因素" tabindex="-1">其实这要分析3个因素， <a class="header-anchor" href="#其实这要分析3个因素" aria-label="Permalink to &quot;其实这要分析3个因素，&quot;">​</a></h2><p>1、突破前的市场结构</p><p>2、当前趋势的强弱度</p><p>3、突破时所处的趋势阶段</p><h2 id="下面分别说说" tabindex="-1">下面分别说说 <a class="header-anchor" href="#下面分别说说" aria-label="Permalink to &quot;下面分别说说&quot;">​</a></h2><h3 id="_1、突破前的市场结构" tabindex="-1">1、突破前的市场结构 <a class="header-anchor" href="#_1、突破前的市场结构" aria-label="Permalink to &quot;1、突破前的市场结构&quot;">​</a></h3><p>突破前，市场只有两种结构，分别是窄幅震荡和非窄幅震荡，</p><p>窄幅震荡时的突破，直接买入即可，因为能量已经进行了足够的积累，突破就是为了释放和高潮。</p><p>如下图所示</p><p><img src="'+r+'" alt="图片"></p><p>这两次突破前都进行了长时间的横盘整理，突破时不管有无基本面提供动能，突破后的走势都很凌厉，突破即买入。</p><p>就像谈恋爱，都谈了三年了，手都没拉过，突然可以拉手了，剩下的就发展很迅速了，因为彼此已经很了解了，女孩既然让你拉手，就说明从内心接受你了。</p><p>突破前如果不是窄幅震荡，同时又处于趋势的起步期，那回调的概率极大，要等回调介入。如下</p><p><img src="'+o+'" alt="图片"></p><h3 id="_2、当前趋势的强弱度" tabindex="-1">2、当前趋势的强弱度 <a class="header-anchor" href="#_2、当前趋势的强弱度" aria-label="Permalink to &quot;2、当前趋势的强弱度&quot;">​</a></h3><p>趋势的强度通过盘面能很直观的看出来，强势多头时价格噌噌噌的往上涨，弱势多头时，价格走三步退两步，螺旋式上涨。所以强趋势时，突破介入，弱趋势时，回调介入。</p><p>弱趋势 <img src="'+i+'" alt="图片"></p><p>强趋势 <img src="'+l+'" alt="图片"></p><h3 id="_3、突破时所处的趋势阶段" tabindex="-1">3、突破时所处的趋势阶段 <a class="header-anchor" href="#_3、突破时所处的趋势阶段" aria-label="Permalink to &quot;3、突破时所处的趋势阶段&quot;">​</a></h3><p>突破时如果处于趋势的起步期，回调介入，如果处于趋势中期，突破介入，末期，回调介入。</p><p>趋势的起步期，走出新高后，大概率回落，因为从波浪的角度看，这是第一波上涨，属于指路之浪，下一步要回撤，走第二浪，给大家上车的机会，就看能否看出来。在趋势中期加速阶段，因为趋势已经明朗，价格会不停的走出新高，所以要突破介入，在趋势的末期，能量已经释放，处于强弩之末，要回调介入。</p><p>多说一句，趋势的起步期和中期加速容易辨别，趋势末期需要方法和技巧。</p><p><img src="'+c+'" alt="图片"></p>',29)]))}const q=t(n,[["render",h]]);export{g as __pageData,q as default};
